(52013, 'Psalms 9:9', 'Psalms', 9, 9, 'څښتن د مظلومانو پناه ځای دی د سختیو په شېبو کې امن ځای دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_9.mp3', '', 1761754199, 1761754199),
(52014, 'Psalms 9:10', 'Psalms', 9, 10, 'هغه خلک چې تا پېژني څښتنه کړي په تا به توکل یوازې نه پرېږدې هغوی چې رجوع کړي تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_10.mp3', '', 1761754199, 1761754199),
(52015, 'Psalms 9:11', 'Psalms', 9, 11, 'د ثنا سندرې ووایئ څښتن ته چې صهیون کې پاچاهي کړي څه چې هغه کړي دي بیان یې کړئ قومونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_11.mp3', '', 1761754199, 1761754199),
(52016, 'Psalms 9:12', 'Psalms', 9, 12, 'اخلي بدل د قاتلانو ځینې او مظلومان یې هم په یاد کې وي فریاد د هغو هېرولی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_12.mp3', '', 1761754199, 1761754199),
(52017, 'Psalms 9:13', 'Psalms', 9, 13, 'ای څښتنه رحم وکړه په ما باندې دښمنان زما، ما څومره ځوروي ورته وګوره ای څښتنه ته د مرګ د خولې ما خلاص کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_13.mp3', '', 1761754199, 1761754199),
(52018, 'Psalms 9:14', 'Psalms', 9, 14, 'نو به ستا ټول صفتونه بیانومه د صهیون په دروازه کې زه به هلته یم خوشحاله ځکه تا یمه ژغورلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_14.mp3', '', 1761754199, 1761754199),
(52019, 'Psalms 9:15', 'Psalms', 9, 15, 'هغه کنده چې قومونو وه ایستلې په کې خپله ولوېدل هغه دام چې دوی ؤ ایښی په کې خپله ونښتل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_15.mp3', '', 1761754199, 1761754199),
(52020, 'Psalms 9:16', 'Psalms', 9, 16, 'مشهور شوی دی څښتن په خپل انصاف بدکاران په خپلو بدو عملونو کې ګېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_16.mp3', '', 1761754199, 1761754199),
(52021, 'Psalms 9:17', 'Psalms', 9, 17, 'ګور د بدکارانو سرنوشت دی هم د هغو ټولو چې هېر کړی یې دی خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_17.mp3', '', 1761754199, 1761754199),
(52022, 'Psalms 9:18', 'Psalms', 9, 18, 'ځکه محتاجان به تر ابده نه هېریږي نه امید به د خوارانو تر ابده بربادیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_18.mp3', '', 1761754199, 1761754199),
(52023, 'Psalms 9:19', 'Psalms', 9, 19, 'ای څښتنه انسان مه پرېږده چې ستا په محکمه کې شي برلاسی کړه قومونه ته حاضر دې خپل حضور ته ته هغوی محاکمه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_19.mp3', '', 1761754199, 1761754199),
(52024, 'Psalms 9:20', 'Psalms', 9, 20, 'وېره واچوه په دوی کې ای څښتنه ترڅو پوه شي چې دوی یوازې انسانان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_20.mp3', '', 1761754199, 1761754199),
(52025, 'Psalms 98:1', 'Psalms', 98, 1, 'څښتن ته ووایئ یوه نوې سندره ځکه کارونه یې عجیبه کړي دي په خپل قدرت او خپل سپېڅلي ځواک یې بریالیتوب تر‌لاسه کړی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_1.mp3', '', 1761754199, 1761754199),
(52026, 'Psalms 98:2', 'Psalms', 98, 2, 'څښتن اعلان کړی دی خپل بری خپل عدالت یې ښکاره کړی دی قومونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_2.mp3', '', 1761754199, 1761754199),
(52027, 'Psalms 98:3', 'Psalms', 98, 3, 'تلپاتې مینه او وفا یې خپله کړله وریاده د اسراییلو قوم ته د ځمکې یو سر نه تر بله سره ټولو لیدلی زمونږ د خدای بری', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_3.mp3', '', 1761754199, 1761754199),
(52028, 'Psalms 98:4', 'Psalms', 98, 4, 'ای ټولې نړۍ، څښتن ته چیغې د خوښۍ ووهئ د خوشحالۍ په سندرو یې ثنا ووایئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_4.mp3', '', 1761754199, 1761754199),
(52029, 'Psalms 98:5', 'Psalms', 98, 5, 'د رباب ساز څښتن ته وغږوئ هم سندرې ورته ووایئ رباب سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_5.mp3', '', 1761754199, 1761754199),
(52030, 'Psalms 98:6', 'Psalms', 98, 6, 'د سرني او د پسونو د ښکرو په اوازونو باندې د خوشحالۍ ووهئ چیغې د څښتن یعنې د نړۍ د پاچا حضور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_6.mp3', '', 1761754199, 1761754199),
(52031, 'Psalms 98:7', 'Psalms', 98, 7, 'دریاب دې په غړمبار شي خپلو ټولو مخلوقاتو سره ځمکه او هرڅوک چې اوسیږي په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_7.mp3', '', 1761754199, 1761754199),
(52032, 'Psalms 98:8', 'Psalms', 98, 8, 'سیندونه دې وپړکوي خپل لاسونه او غرونه دې ووایي سندرې د خوښۍ یو د بله سره د څښتن حضور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_8.mp3', '', 1761754199, 1761754199),
(52033, 'Psalms 98:9', 'Psalms', 98, 9, 'ځکه څښتن راځي د دنیا د قضاوت دپاره د نړۍ د خلکو قضاوت به په عدالت او په انصاف وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms98_verse_9.mp3', '', 1761754199, 1761754199),
(52034, 'Judges 10:1', 'Judges', 10, 1, 'د ابیملک د مړینې څخه وروسته د فواه زوی او د دودو لمسی تولع د اسراییلو د ژغورلو دپاره راغی. هغه د یساکار د قبیلې څخه ؤ او د افرایم په غرنۍ سیمه کې د شامیر په ښارګوټي کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_1.mp3', '', 1761754199, 1761754199),
(52035, 'Judges 10:2', 'Judges', 10, 2, 'هغه درویشت کاله د اسراییلو مشر ؤ. بیا هغه مړ شو او په شامیر کې ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_2.mp3', '', 1761754199, 1761754199),
(52036, 'Judges 10:3', 'Judges', 10, 3, 'د تولع څخه وروسته جلعادي یاییر راغی. هغه دوه ویشت کاله د اسراییلو مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_3.mp3', '', 1761754199, 1761754199),
(52037, 'Judges 10:4', 'Judges', 10, 4, 'هغه دېرش زامن درلودل چې هر یو یې په خپل خره باندې سپرېده. هغوی په جلعاد کې دېرش ښارګوټي درلودل چې تر نن ورځې پورې د یاییر د ښارګوټو په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_4.mp3', '', 1761754199, 1761754199),
(52038, 'Judges 10:5', 'Judges', 10, 5, 'کله چې یاییر مړ شو، هغه په قامون کې ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_5.mp3', '', 1761754199, 1761754199),
(52039, 'Judges 10:6', 'Judges', 10, 6, 'اسراییلیانو یوځل بیا د څښتن په وړاندې ګناه وکړه او د بعل او عشتاروت بتانو او د سوریې، صیدون، موآب، عمون او فلسطین خدایانو ته یې په عبادت لاس پورې کړ. هغوی څښتن پرېښود او د هغه عبادت کول یې بس کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_6.mp3', '', 1761754199, 1761754199),
(52040, 'Judges 10:7', 'Judges', 10, 7, 'نو څښتن په هغوی باندې په قهر شو او هغوی یې فلسطینیانو او عمونیانو ته په لاس ورکړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_7.mp3', '', 1761754199, 1761754199),
(52041, 'Judges 10:8', 'Judges', 10, 8, 'اتلس کاله هغوی په اسراییلیانو باندې ظلم وکړ او ټول اسراییلیان یې چې په جلعاد کې د اردن د سیند ختیځ خواته د اموریانو په هېواد کې اوسېدل، وځورول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_8.mp3', '', 1761754199, 1761754199),
(52042, 'Judges 10:9', 'Judges', 10, 9, 'عمونیان د یهودا، بنیامین او افرایم د قبیلو سره د جګړې دپاره حتی د اردن د سیند څخه تېر شول. اسراییلیان په ډېر لوی مصیبت اخته شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_9.mp3', '', 1761754199, 1761754199),
(52043, 'Judges 10:10', 'Judges', 10, 10, 'بیا اسراییلیانو څښتن ته فریاد وکړ او ویې ویل: «مونږ ستا په وړاندې ګناه کړې ده، ځکه چې ته زمونږ خدای یې او مونږ ته پرېښودلې او د بعل د بتانو عبادت مو پیل کړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_10.mp3', '', 1761754199, 1761754199),
(52044, 'Judges 10:11', 'Judges', 10, 11, 'څښتن هغوی ته دا ځواب ورکړ: «هغه وخت چې مصریانو، اموریانو، عمونیانو، فلسطینیانو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_11.mp3', '', 1761754199, 1761754199),
(52045, 'Judges 10:12', 'Judges', 10, 12, 'صیدونیانو، عمالیقیانو او معونیانو په تاسو باندې ظلم کاوه او تاسو ماته فریاد وکړ، ایا د هغوی څخه مې ونه ژغورلئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_12.mp3', '', 1761754199, 1761754199),
(52046, 'Judges 10:13', 'Judges', 10, 13, 'خو تاسو زه پرېښودم او د نورو خدایانو عبادت مو وکړ، نو زه به نور تاسو ونه ژغورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_13.mp3', '', 1761754199, 1761754199),
(52047, 'Judges 10:14', 'Judges', 10, 14, 'لاړ شئ هغو خدایانو ته فریاد وکړئ چې تاسو خپلو ځانونو دپاره غوره کړي دي. کله چې د تکلیف سره مخامخ کېږئ، نو پرېږدئ چې هغوی مو وژغوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_14.mp3', '', 1761754199, 1761754199),
(52048, 'Judges 10:15', 'Judges', 10, 15, 'خو د اسراییلو خلکو څښتن ته وویل: «مونږ ګناه کړې ده. څه چې ستا خوښه وي زمونږ سره یې وکړه، خو اوس مونږ د عمونیانو څخه وژغوره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_15.mp3', '', 1761754199, 1761754199),
(52049, 'Judges 10:16', 'Judges', 10, 16, 'نو هغوی د پردیو خدایانو څخه لاس واخیست او د څښتن عبادت یې پیل کړ. نو څښتن نور د هغوی تکلیفونه نه شول لیدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_16.mp3', '', 1761754199, 1761754199),
(52050, 'Judges 10:17', 'Judges', 10, 17, 'بیا د عمونیانو لښکرې د جنګ دپاره تیارې شوې او په جلعاد کې یې خېمې ودرولې. اسراییلیان سره راټول شول او د جلعاد په مصفه کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_17.mp3', '', 1761754199, 1761754199),
(52051, 'Judges 10:18', 'Judges', 10, 18, 'د جلعاد مشرانو یو بل ته وویل: «هرچا چې لومړی په عمونیانو باندې حمله وکړه، هغه به د جلعاد د ټولو خلکو مشر شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges10_verse_18.mp3', '', 1761754199, 1761754199),
(52052, 'Nehemiah 6:1', 'Nehemiah', 6, 1, 'سنبلط، طوبیا او جشم چې عرب ؤ او زمونږ نورو دښمنانو واورېدل چې مونږ د دېوال د ودانولو کار پای ته رسولی دی او په هغه کې هېڅ سوری پاتې نه دی. یوازې د دروازو د پلو د ایښودلو کار پاتې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_1.mp3', '', 1761754199, 1761754199),
(52053, 'Nehemiah 6:2', 'Nehemiah', 6, 2, 'نو سنبلط او جشم ماته یو پیغام راولېږه او دا وړاندیز یې وکړ چې د هغوی سره د اونو په ډاګ کې په یوه کلي کې وګورم. زه پوه شوم چې دا د هغوی یو چل ؤ او غوښتل یې چې ماته زیان ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_2.mp3', '', 1761754199, 1761754199),
(52054, 'Nehemiah 6:3', 'Nehemiah', 6, 3, 'هغوی ته مې استازي ورولېږل چې داسې ورته ووایي: «زه په یو مهم کار باندې بوخت یم. زه نه شم کولای چې خپل کار پرېږدم، هلته درشم او ستاسو سره وګورم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_3.mp3', '', 1761754199, 1761754199),
(52055, 'Nehemiah 6:4', 'Nehemiah', 6, 4, 'هغوی څلور ځلې هماغه پیغام راولېږه او ما ورته هر ځل هماغه ځواب ورلېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_4.mp3', '', 1761754199, 1761754199),
(52056, 'Nehemiah 6:5', 'Nehemiah', 6, 5, 'نو سنبلط خپل خدمتګار د پنځم ځل دپاره د یو لیک سره راولېږه، دا یو سرخلاصی لیک ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_5.mp3', '', 1761754199, 1761754199),
(52057, 'Nehemiah 6:6', 'Nehemiah', 6, 6, 'په هغه کې داسې لیکل شوي وو: «جشم وایي چې د ګاونډیو قومونو په منځ کې داسې اوازې دي چې ته او یهودیان اراده لرئ چې سرکښي وکړئ، نو په دې خاطر تاسو دا دېوال ودانوئ. دا هم وایي چې ته غواړې خپل ځان د هغوی پاچا کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_6.mp3', '', 1761754199, 1761754199),
(52058, 'Nehemiah 6:7', 'Nehemiah', 6, 7, 'همدارنګه تا نبیان هم ټاکلي دي چې په اورشلیم کې داسې اعلان وکړي چې نحمیا د یهودا پاچا دی. نو دا خبر به بېرته پاچا ته ورسیږي، ښه به دا وي چې زما سره وګورې، ترڅو په دې اړه یو د بل سره مشوره وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_7.mp3', '', 1761754199, 1761754199),
(52059, 'Nehemiah 6:8', 'Nehemiah', 6, 8, 'ما هغه ته ځواب ورولېږه: «ته چې څه وایې په هغې کې هېڅ رښتیا نشته. دا ټولې خبرې تا د خپله ځانه جوړې کړې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_8.mp3', '', 1761754199, 1761754199),
(52060, 'Nehemiah 6:9', 'Nehemiah', 6, 9, 'هغوی ټولو هڅه کوله چې مونږ ووېروي او د دې کار څخه لاس واخلو. خو ما خدای ته دعا وکړه چې ماته قوت راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_9.mp3', '', 1761754199, 1761754199),
(52061, 'Nehemiah 6:10', 'Nehemiah', 6, 10, 'شمعیه د دلایا زوی او د مهیتبییل لمسي نه شو کولای چې خپل کور پرېږدي، نو زه د هغه د لیدلو دپاره لاړم. چې کله یې زه ولیدم، ویې ویل: «باید د خدای په کور کې پټ شو او دروازې قلف کړو، ځکه چې هغوی د شپې راځي چې تا ووژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_10.mp3', '', 1761754199, 1761754199),
(52062, 'Nehemiah 6:11', 'Nehemiah', 6, 11, 'ما ځواب ورکړ: «زه داسې سړی نه یم چې وتښتم او پټ شم. ایا ته فکر کوې چې زه به د خدای په کور کې په پټېدلو سره خپل ژوند وژغورم؟ زه به دا کار ونه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_11.mp3', '', 1761754199, 1761754199),
(52063, 'Nehemiah 6:12', 'Nehemiah', 6, 12, 'کله چې ما په دې اړه فکر وکړ نو پوه شوم چې خدای شمعیه نه دی رالېږلی، بلکې طوبیا او سنبلط هغه ته رشوت ورکړی دی چې ماته دا خبرداری راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_12.mp3', '', 1761754199, 1761754199),
(52064, 'Nehemiah 6:13', 'Nehemiah', 6, 13, 'هغوی هغه اجیر نیولی ؤ چې ما ووېروي او ګناه وکړم، ترڅو هغوی وکولای شي چې زما نوم بد کړي او ومې شرموي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_13.mp3', '', 1761754199, 1761754199),
(52065, 'Nehemiah 6:14', 'Nehemiah', 6, 14, 'ما دعا وکړه: «ای زما خدایه، هغه څه چې طوبیا او سنبلط وکړل هغه در په یاد کړه او هغوی ته سزا ورکړه. همدارنګه نوعدیه پیغمبره او نور ټول نبیان در په یاد کړه چې غوښتل یې ما ووېروي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_14.mp3', '', 1761754199, 1761754199),
(52066, 'Nehemiah 6:15', 'Nehemiah', 6, 15, 'دېوال په دوه پنځوس ورځو کې د ایلول د میاشتې په پنځه ویشتمه نېټه پای ته ورسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_15.mp3', '', 1761754199, 1761754199),
(52067, 'Nehemiah 6:16', 'Nehemiah', 6, 16, 'کله چې زمونږ ټول دښمنان خبر شول چې کار پای ته ورسېده، نو شاوخوا قومونه ووېرېدل او رسوا شول، ځکه چې هغوی په دې پوه شول چې زمونږ خدای د دېوال په بیا ودانولو کې زمونږ سره مرسته کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_16.mp3', '', 1761754199, 1761754199),
(52068, 'Nehemiah 6:17', 'Nehemiah', 6, 17, 'په دې ټوله موده کې یهودي مشرانو او طوبیا یو بل ته لیکونه استول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_17.mp3', '', 1761754199, 1761754199),
(52069, 'Nehemiah 6:18', 'Nehemiah', 6, 18, 'دوه دلیلونه وو چې په یهودا کې ډېرو خلکو د طوبیا سره قسم کړی ؤ: یو دا چې شکنیا د آرح زوی د هغه خسر ؤ او بل دا چې د طوبیا زوی یهوحانان د برکیا د زوی مشلام د لور سره واده کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_18.mp3', '', 1761754199, 1761754199),
(52070, 'Nehemiah 6:19', 'Nehemiah', 6, 19, 'خلکو به زما په مخکې د طوبیا د ښو کارونو په اړه خبرې کولې او زما خبرې به یې هغه ته رسولې. نو طوبیا به لیکونه رالېږل چې ما ووېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah6_verse_19.mp3', '', 1761754199, 1761754199),
(52071, 'Micah 4:1', 'Micah', 4, 1, 'راتلونکو ورځو کې به په کوم غر چې دی جوړ شوی د څښتن کور وي به نړۍ کې دا غر لوړ له ټولو غرونو څخه هغه به لوړ وي ټولو غونډیو څخه وي به قومونه ورروان هلته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_1.mp3', '', 1761754199, 1761754199),
(52072, 'Micah 4:2', 'Micah', 4, 2, 'هغوی به راشي وبه وایي داسې: راځئ ورخېژو د څښتن غره ته مونږ پورته شو کور ته د یعقوب د خدای هلته به وښایي هغه مونږ ته خپلې لارې او مونږ به وکړو هغه کار چې وي خوښ د هغه ځکه چې شریعت د څښتن به له صهیونه راشي د ده کلام به راشي له اورشلیمه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_2.mp3', '', 1761754199, 1761754199),
(52073, 'Micah 4:3', 'Micah', 4, 3, 'څښتن به وکړي قضاوت د ډېرو قومونو ترمنځ د قاضي په شان به حل کړي د قوي او لېرې قومونو شخړې خپلو تورو نه به جوړ کړي خلک پال د قلبې نېزې بدلې په لورونو به کړي بیا به هېڅکله قومونه غوره نه کړي د جنګ لاره بیا به هېڅکله دوی نه نیسي د جنګ تیاری', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_3.mp3', '', 1761754199, 1761754199),
(52074, 'Micah 4:4', 'Micah', 4, 4, 'هغوی به ژوند کوي په سوله کې خپل د انګورو په باغونو او انځرو لاندې او هېڅوک به نه وي چې دوی ووېروي دغه وعده کړې ده مطلق قادر څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_4.mp3', '', 1761754199, 1761754199),
(52075, 'Micah 4:5', 'Micah', 4, 5, 'هر یو قوم د خپل خدای عبادت او اطاعت کوي، خو مونږ به تل ترتله د خپل څښتن خدای عبادت او اطاعت کوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_5.mp3', '', 1761754199, 1761754199),
(52076, 'Micah 4:6', 'Micah', 4, 6, 'څښتن وایي: «هغه وخت راروان دی چې زه به هغه ګوډ خلک سره راټول کړم چې سزا مې ورته ورکړې وه او شړل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_6.mp3', '', 1761754199, 1761754199),
(52077, 'Micah 4:7', 'Micah', 4, 7, 'هغه خلک چې ګوډ شوي دي او په جلاوطنۍ کې پاتې دي، د هغوی نه به یو لوی قوم جوړ شي. نو له همدا اوس نه تر ابده پورې به زه څښتن د صهیون په غره کې په هغوی باندې حکومت وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_7.mp3', '', 1761754199, 1761754199),
(52078, 'Micah 4:8', 'Micah', 4, 8, 'او ای اورشلیمه، چېرته چې خدای لکه د څارنې د برج نه د شپانه په شان په خپلو خلکو باندې پام کاوه، ته به یوځل بیا د خپلې پاچاهۍ پایتخت شې، لکه په یو وخت کې چې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_8.mp3', '', 1761754199, 1761754199),
(52079, 'Micah 4:9', 'Micah', 4, 9, 'اوس دومره په لوړ اواز ولې چیغې وهې؟ ته ولې د هغې ښځې په شان چې د لنګون په درد باندې اخته وي، په تکلیف یې؟ ایا دا په دې خاطر چې پاچا نه لرئ او مشاوران مو مړه شوي دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_9.mp3', '', 1761754199, 1761754199),
(52080, 'Micah 4:10', 'Micah', 4, 10, 'ای د اورشلیم ګرانو خلکو، د هغې ښځې په شان تاوېږئ، راتاوېږئ او زګېروي کوئ چې د لنګون په درد اخته وي، ځکه چې تاسو باید ښار پرېږدئ او په یو ډاګ کې واوسېږئ. تاسو به بابل ته لاړ شئ، خو هلته به څښتن تاسو وژغوري او د خپلو دښمنانو نه به مو بېرته ازاد کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_10.mp3', '', 1761754199, 1761754199),
(52081, 'Micah 4:11', 'Micah', 4, 11, 'ډېر قومونه سره راټول شوي دي چې حمله درباندې وکړي. هغوی وایي: «اورشلیم باید وران شي! مونږ به ووینو چې دا ښار به په کنډوالو باندې بدل شي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_11.mp3', '', 1761754199, 1761754199),
(52082, 'Micah 4:12', 'Micah', 4, 12, 'خو دا قومونه په دې نه پوهیږي چې د څښتن خیالونه څه دي او د هغه اراده څه ده. هغوی په دې باندې نه پوهیږي چې دوی د دې دپاره راټول کړای شوي دي چې داسې سزا ورته ورکړل شي لکه څنګه چې ګېډۍ د غوبل دپاره راوړل شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_12.mp3', '', 1761754199, 1761754199),
(52083, 'Micah 4:13', 'Micah', 4, 13, 'څښتن وایي: «ای د اورشلیم ګرانو خلکو، پاڅېږئ او خپلو دښمنانو ته داسې سزا ورکړئ لکه غنم چې غوبل کیږي! زه به تاسو د هغه غویي په شان چې اوسپنیز ښکرونه او برنجي سومان لري، قوي کړم. تاسو به ډېر قومونه ټوټې ټوټې کړئ او هغوی چې په زور‌زیاتي باندې کوم مال دولت لاسته راوړی دی، هغه به ما یعنې د ټولې دنیا څښتن ته وقف کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah4_verse_13.mp3', '', 1761754199, 1761754199),
(52084, 'Genesis 32:1', 'Genesis', 32, 1, 'یعقوب هم په خپله مخه لاړ او د خدای فرښتې ورسره مخامخ شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_1.mp3', '', 1761754199, 1761754199),
(52085, 'Genesis 32:2', 'Genesis', 32, 2, 'کله چې یعقوب هغوی ولیدلې، ویې ویل: «دا د خدای کمپ دی.» نو د هغه ځای نوم یې محنایم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_2.mp3', '', 1761754199, 1761754199),
(52086, 'Genesis 32:3', 'Genesis', 32, 3, 'یعقوب د ځان څخه مخکې خپل ورور عیسو ته چې د ادوم په خاوره کې اوسېده، استازي ولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_3.mp3', '', 1761754199, 1761754199),
(52087, 'Genesis 32:4', 'Genesis', 32, 4, 'هغوی ته یې وویل: «زما بادار عیسو ته ووایئ چې ستا غلام یعقوب داسې وایي: ‹زه د لابان سره اوسېدم او تر‌اوسه پورې هلته پاتې وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_4.mp3', '', 1761754199, 1761754199),
(52088, 'Genesis 32:5', 'Genesis', 32, 5, 'زه د پادو، خرو، پسونو، وزو، غلامانو او وینځو خاوند شوی یم. اوس مې خپل بادار ته دغه پیغام ولېږه چې په ما باندې مهرباني وکړې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_5.mp3', '', 1761754199, 1761754199),
(52089, 'Genesis 32:6', 'Genesis', 32, 6, 'کله چې استازي بېرته یعقوب ته راستانه شول، هغوی وویل: «مونږ ستا ورور عیسو ته لاړو او هغه د څلور سوه کسانو سره ستا د لیدلو دپاره راروان دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_6.mp3', '', 1761754199, 1761754199),
(52090, 'Genesis 32:7', 'Genesis', 32, 7, 'نو یعقوب ډېر ووېرېد او پرېشانه شو. هغه خپل خلک او رمې، پادې او اوښان په دوه ډلو باندې ووېشل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_7.mp3', '', 1761754199, 1761754199),
