(52093, 'Genesis 32:10', 'Genesis', 32, 10, 'زه د هغو ټولو مهربانیو او وفاداریو وړ نه یم چې د خپل غلام سره دې کړي دي. کله چې زه د اردن د سیند څخه تېرېدم، نو زما سره یوازې یوه امسا وه. او اوس زه د دوو لویو ډلو خاوند یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_10.mp3', '', 1761754199, 1761754199),
(52094, 'Genesis 32:11', 'Genesis', 32, 11, 'اوس سوال کوم چې ما د خپل ورور عیسو له لاسه وژغوره، ځکه زه وېرېږم چې هغه به راشي او په مونږ به حمله وکړي او مونږ به د ښځو او ماشومانو سره له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_11.mp3', '', 1761754199, 1761754199),
(52095, 'Genesis 32:12', 'Genesis', 32, 12, 'بلکې هغه وعده رایاده کړه چې تا زما سره کړې وه چې ما سره به ښه کوې او زما اولاده به د بحیرې د شګو په شان دومره زیاتوې چې ونه شمېرل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_12.mp3', '', 1761754199, 1761754199),
(52096, 'Genesis 32:13', 'Genesis', 32, 13, 'هغه هلته شپه تېره کړه او هرڅه چې یې درلودل د هغو څخه یې د خپل ورور عیسو دپاره سوغات غوره کړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_13.mp3', '', 1761754199, 1761754199),
(52097, 'Genesis 32:14', 'Genesis', 32, 14, 'دوه سوه وزې او شل سېرلي، دوه سوه مېږې او شل پسونه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_14.mp3', '', 1761754199, 1761754199),
(52098, 'Genesis 32:15', 'Genesis', 32, 15, 'دېرش اوښې د هغو د بچیو سره، څلوېښت غواګانې او لس غویان، شل خرې او لس خره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_15.mp3', '', 1761754199, 1761754199),
(52099, 'Genesis 32:16', 'Genesis', 32, 16, 'هغوی یې په دوه ډلو ووېشل او خپلو غلامانو ته یې وسپارل او هغوی ته یې وویل: «زما څخه مخکې ځئ او د ډلو ترمنځ فاصله پرېږدئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_16.mp3', '', 1761754199, 1761754199),
(52100, 'Genesis 32:17', 'Genesis', 32, 17, 'یعقوب هغه غلام ته چې مخکې روان ؤ، حکم وکړ: «کله چې زما ورور عیسو ستا سره مخامخ شي او پوښتنه وکړي چې ستاسو بادار څوک دی؟ تاسو چېرې ځئ؟ او ستاسو په مخکې دا حیوانات د چا دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_17.mp3', '', 1761754199, 1761754199),
(52101, 'Genesis 32:18', 'Genesis', 32, 18, 'باید ووایې: ‹دا ستا د غلام یعقوب دي او هغه یې د سوغات په توګه خپل بادار عیسو دپاره لېږلي دي او په خپله یعقوب هم مونږ پسې راروان دی.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_18.mp3', '', 1761754199, 1761754199),
(52102, 'Genesis 32:19', 'Genesis', 32, 19, 'همدارنګه هغه دوهم، درېم او ټولو پادوانانو ته امر وکړ: «کله چې د عیسو سره مخامخ شئ، نو همداسې به ورته وایئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_19.mp3', '', 1761754199, 1761754199),
(52103, 'Genesis 32:20', 'Genesis', 32, 20, 'خامخا ووایئ چې ستا غلام یعقوب مونږ پسې راروان دی.» ځکه هغه فکر کاوه چې د دې سوغاتونو په وسیله به چې مخکې مې لېږلي دي د هغه قهر سوړ کړم او چې کله د هغه سره مخامخ شم، کېدای شي چې هغه ما وبخښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_20.mp3', '', 1761754199, 1761754199),
(52104, 'Genesis 32:21', 'Genesis', 32, 21, 'نو د یعقوب سوغاتونه له هغه څخه مخکې لاړل، خو هغه شپه په کمپ کې تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_21.mp3', '', 1761754199, 1761754199),
(52105, 'Genesis 32:22', 'Genesis', 32, 22, 'په هماغه شپه یعقوب پاڅېد او خپلې دوه ښځې، دوه وینځې او خپل یوولس زامن یې واخیستل او د یبوق د سیند په ګودر باندې پورې وتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_22.mp3', '', 1761754199, 1761754199),
(52106, 'Genesis 32:23', 'Genesis', 32, 23, 'وروسته له دې چې هغوی یې د سیند څخه پورې ویستل، هغه خپل مال او شتمني هم ولېږله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_23.mp3', '', 1761754199, 1761754199),
(52107, 'Genesis 32:24', 'Genesis', 32, 24, 'نو یعقوب یوازې پاتې شو او یو کس راغی او د هغه سره یې د سهار تر رڼایۍ پورې غېږه ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_24.mp3', '', 1761754199, 1761754199),
(52108, 'Genesis 32:25', 'Genesis', 32, 25, 'نو کله چې هغه کس ولیدل چې په یعقوب باندې بری نه شي موندلی، نو د یعقوب په ورون باندې یې ګوزار وکړ او د هغه ورون له بنده وخوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_25.mp3', '', 1761754199, 1761754199),
(52109, 'Genesis 32:26', 'Genesis', 32, 26, 'نو بیا هغه سړي وویل: «ما پرېږده چې لاړ شم، ځکه چې لمر په راختلو دی.» خو یعقوب ځواب ورکړ: «ترڅو چې ماته برکت رانه کړې، تا نه پرېږدم چې لاړ شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_26.mp3', '', 1761754199, 1761754199),
(52110, 'Genesis 32:27', 'Genesis', 32, 27, 'هغه کس د هغه څخه پوښتنه وکړه: «ستا نوم څه دی؟» هغه ځواب ورکړ: «یعقوب.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_27.mp3', '', 1761754199, 1761754199);